class Solution
{
public:
    int minArea(vector<vector<char>>& image, int x, int y)
    {
        int m = image.size(), n = image[0].size();
        auto rowHasBlack = [&](int r) {
            for (int c = 0; c < n; ++c)
            {
                if (image[r][c] == '1') return true;
            }
            return false;
        };
        auto colHasBlack = [&](int c) {
            for (int r = 0; r < m; ++r)
            {
                if (image[r][c] == '1') return true;
            }
            return false;
        };
        int lo = 0, hi = x;
        while (lo < hi)
        {
            int mid = lo + (hi - lo) / 2;
            if (rowHasBlack(mid)) hi = mid;
            else lo = mid + 1;
        }
        int top = lo;
        lo = x; hi = m;
        while (lo < hi)
        {
            int mid = lo + (hi - lo) / 2;
            if (rowHasBlack(mid)) lo = mid + 1;
            else hi = mid;
        }
        int bottom = lo;
        lo = 0; hi = y;
        while (lo < hi)
        {
            int mid = lo + (hi - lo) / 2;
            if (colHasBlack(mid)) hi = mid;
            else lo = mid + 1;
        }
        int left = lo;
        lo = y; hi = n;
        while (lo < hi)
        {
            int mid = lo + (hi - lo) / 2;
            if (colHasBlack(mid)) lo = mid + 1;
            else hi = mid;
        }
        return (bottom - top) * (hi - left);
    }
};
